    const int32_t crs2 = GeometryCrsSrid(args.data[2].GetType());
    auto in3 = ListVector::GetData(args.data[3]);
    auto &ch3 = ListVector::GetEntry(args.data[3]);
    ch3.Flatten(ListVector::GetListSize(args.data[3]));
